<svelte:options runes={true} />

<script lang="ts">
  // Live and assigned work across projects.
  import AgentPulse from '../../../lib/components/AgentPulse.svelte';
  import LiveWorkRow from '../../../lib/components/LiveWorkRow.svelte';
  import { formatDate, isOverdue } from '../../../lib/state';
  import { priorityLabels, stateLabels } from '../../constants';
  import { openWorkTask } from '../../drawer/open';
  import { loadMyWork, selectMyWorkView } from '../../myWork';
  import { setView } from '../../routing';
  import { live } from '../../state/live.svelte';
  import { myWork } from '../../state/myWork.svelte';
  import { releasePlan } from '../../state/releasePlan.svelte';
  import { workspace } from '../../state/workspace.svelte';
  import { agentLabelForTask, isActionNeeded, projectForTask, releaseOptionLabel, semanticStateForTask, taskDueClass, taskReleaseName } from '../../taskQueries';
  import type { WorkFilter } from '../../types';
</script>

<section class="page-heading"><div><div class="breadcrumbs"><span>Workspace</span><span>/</span><span>Personal</span></div><h1>My work</h1><p>{myWork.myWorkView === 'live' ? 'Live agent work across every project, grouped by the attention it needs.' : 'Everything assigned or claimed by you, across projects.'}</p></div><div class="heading-actions"><div class="work-view-toggle" role="group" aria-label="My work source"><button class:active={myWork.myWorkView === 'live'} class="button quiet-button" type="button" aria-pressed={myWork.myWorkView === 'live'} on:click={() => selectMyWorkView('live')}>Live</button><button class:active={myWork.myWorkView === 'assigned'} class="button quiet-button" type="button" aria-pressed={myWork.myWorkView === 'assigned'} on:click={() => selectMyWorkView('assigned')}>Assigned</button></div><button class="button quiet-button" type="button" on:click={loadMyWork}>↻ Refresh</button><select class="release-filter-select" aria-label="Filter my work by focus" bind:value={myWork.myWorkReleaseFilter} on:change={loadMyWork}><option value="all">All focus areas</option>{#each releasePlan.allReleaseOptions as release}<option value={release.id}>{releaseOptionLabel(release)}</option>{/each}<option value="unassigned">No focus</option></select></div></section>
{#if myWork.myWorkError}<div class="inline-alert error content-alert" role="alert"><span>!</span>{myWork.myWorkError}<button class="text-button" type="button" on:click={loadMyWork}>Retry</button></div>{/if}
{#if myWork.myWorkLoading}<div class="list-skeleton">{#each [1, 2, 3] as item}<div></div>{/each}</div>{:else if !myWork.visibleMyWorkTasks.length}<div class="empty-state"><div class="empty-icon">◌</div><h2>{myWork.myWorkView === 'live' ? 'No live work yet' : 'No work assigned yet'}</h2><p>{myWork.myWorkView === 'live' ? 'Agent updates and attention items will appear here as work moves across projects.' : 'Tasks claimed or assigned to you will show up here.'}</p><button class="button primary" type="button" on:click={() => workspace.activeProject && setView('board')}>Browse the board</button></div>{:else if myWork.myWorkView === 'assigned'}<section class="work-list">{#each myWork.visibleMyWorkTasks as task (task.id)}<button class="work-row" type="button" on:click={() => openWorkTask(task)}><span class="work-project-dot" style={`--project-color: ${projectForTask(task)?.color || '#6d5efc'}`}></span><span class="work-main"><span class="work-row-top"><span class="task-key">{task.key}</span><span class={`priority-pill priority-${task.priority}`}>{priorityLabels[task.priority]}</span>{#if taskReleaseName(task)}<span class="release-chip">{taskReleaseName(task)}</span>{/if}</span><strong>{task.title}</strong><span class="work-project-name">{projectForTask(task)?.name || 'Project'}</span></span><span class="work-column">{myWork.myWorkColumnsByProject[task.project_id]?.find((column) => column.id === task.column_id)?.name || 'In progress'}</span><span class={`work-due ${taskDueClass(task)}`}>{task.due_at ? `${isOverdue(task.due_at) ? 'Overdue · ' : ''}${formatDate(task.due_at)}` : 'No due date'}</span><span class="row-arrow">→</span></button>{/each}</section>{:else}
  <section class="live-work" class:action-filter={myWork.myWorkFilter === 'action-needed'} aria-labelledby="live-work-heading">
    <div class="live-work-toolbar">
      <div><span class="eyebrow">Cross-project coordination</span><h2 id="live-work-heading">{myWork.myWorkView === 'live' ? 'Live work' : 'Assigned work'}</h2><p>{myWork.myWorkView === 'live' ? `${myWork.myWorkTasks.length} live assignment${myWork.myWorkTasks.length === 1 ? '' : 's'} across projects.` : `${myWork.myWorkTasks.length} assignment${myWork.myWorkTasks.length === 1 ? '' : 's'} currently assigned or claimed by you.`}</p></div>
      <div class="live-work-filters" role="group" aria-label="Filter live work">
        {#each [{ value: 'all', label: 'All' }, { value: 'action-needed', label: 'Action needed' }, { value: 'stale', label: 'Stale' }, { value: 'waiting', label: 'Waiting' }, { value: 'handoff', label: 'Handoff' }, { value: 'verifying', label: 'Verifying' }, { value: 'working', label: 'Working' }] as option}
          <button class:active={myWork.myWorkFilter === option.value} class="live-work-filter" type="button" aria-pressed={myWork.myWorkFilter === option.value} on:click={() => myWork.myWorkFilter = option.value as WorkFilter}>{option.label}{#if option.value === 'action-needed' && myWork.myWorkTasks.filter((task) => isActionNeeded(task, live.pulseClock)).length}<span>{myWork.myWorkTasks.filter((task) => isActionNeeded(task, live.pulseClock)).length}</span>{/if}</button>
        {/each}
      </div>
    </div>
    {#if myWork.myWorkColumnsLoading}<div class="live-work-note"><span class="spinner"></span> Loading project columns…</div>{/if}
    {#if myWork.myWorkFilter === 'all' || myWork.myWorkFilter === 'action-needed'}
      <section class="live-work-group action-needed-group" aria-labelledby="action-needed-heading"><div class="live-work-group-heading"><div><h3 id="action-needed-heading">Action needed</h3><p>Waiting, handoff, stale, or explicitly blocked by an agent.</p></div><strong>{myWork.myWorkActionRows.length}</strong></div>{#if myWork.myWorkActionRows.length}{#each myWork.myWorkActionRows as row (row.task.id)}<button class="work-row live-work-row" type="button" on:click={() => openWorkTask(row.task)}><span class="work-project-dot" style={`--project-color: ${row.project?.color || '#6d5efc'}`}></span><span class="work-main"><span class="work-row-top"><span class="task-key">{row.task.key}</span><span class={`priority-pill priority-${row.task.priority}`}>{priorityLabels[row.task.priority]}</span>{#if taskReleaseName(row.task)}<span class="release-chip">{taskReleaseName(row.task)}</span>{/if}</span><strong>{row.task.title}</strong><span class="work-project-name">{row.project?.name || 'Project'} · {row.column?.name || stateLabels[semanticStateForTask(row.task, myWork.myWorkColumnsByProject[row.task.project_id] || [])] || 'In progress'}</span></span><span class="live-work-state"><AgentPulse task={row.task} now={live.pulseClock} actorLabel={agentLabelForTask(row.task)} /></span><span class="row-arrow">→</span></button>{/each}{:else}<p class="live-work-empty">Nothing needs your attention right now.</p>{/if}</section>
    {/if}
        {#if myWork.myWorkFilter === 'all' || myWork.myWorkFilter === 'stale'}
      <section class="live-work-group stale-group" aria-labelledby="stale-heading"><div class="live-work-group-heading"><div><h3 id="stale-heading">Stale</h3><p>No update has arrived for at least 15 minutes.</p></div><strong>{myWork.myWorkStaleRows.length}</strong></div>{#if myWork.myWorkStaleRows.length}{#each myWork.myWorkStaleRows as row (row.task.id)}<LiveWorkRow task={row.task} project={row.project} column={row.column} now={live.pulseClock} actorLabel={agentLabelForTask(row.task)} onOpen={openWorkTask} />{/each}{:else}<p class="live-work-empty">No stale agent updates.</p>{/if}</section>
    {/if}
        {#if myWork.myWorkFilter === 'all' || myWork.myWorkFilter === 'waiting'}
      <section class="live-work-group waiting-group" aria-labelledby="waiting-heading"><div class="live-work-group-heading"><div><h3 id="waiting-heading">Waiting</h3><p>An agent is waiting for a dependency, answer, or decision.</p></div><strong>{myWork.myWorkWaitingRows.length}</strong></div>{#if myWork.myWorkWaitingRows.length}{#each myWork.myWorkWaitingRows as row (row.task.id)}<LiveWorkRow task={row.task} project={row.project} column={row.column} now={live.pulseClock} actorLabel={agentLabelForTask(row.task)} onOpen={openWorkTask} />{/each}{:else}<p class="live-work-empty">No agent work is waiting.</p>{/if}</section>
    {/if}
        {#if myWork.myWorkFilter === 'all' || myWork.myWorkFilter === 'handoff'}
      <section class="live-work-group handoff-group" aria-labelledby="handoff-heading"><div class="live-work-group-heading"><div><h3 id="handoff-heading">Handoff</h3><p>Agent context is ready for a human or another agent.</p></div><strong>{myWork.myWorkHandoffRows.length}</strong></div>{#if myWork.myWorkHandoffRows.length}{#each myWork.myWorkHandoffRows as row (row.task.id)}<LiveWorkRow task={row.task} project={row.project} column={row.column} now={live.pulseClock} actorLabel={agentLabelForTask(row.task)} onOpen={openWorkTask} />{/each}{:else}<p class="live-work-empty">No handoffs are waiting.</p>{/if}</section>
    {/if}
    {#if myWork.myWorkFilter === 'all' || myWork.myWorkFilter === 'verifying'}
      <section class="live-work-group" aria-labelledby="verifying-heading"><div class="live-work-group-heading"><div><h3 id="verifying-heading">Verifying</h3><p>Agent work waiting for a final check.</p></div><strong>{myWork.myWorkVerifyingRows.length}</strong></div>{#if myWork.myWorkVerifyingRows.length}{#each myWork.myWorkVerifyingRows as row (row.task.id)}<button class="work-row live-work-row" type="button" on:click={() => openWorkTask(row.task)}><span class="work-project-dot" style={`--project-color: ${row.project?.color || '#6d5efc'}`}></span><span class="work-main"><span class="work-row-top"><span class="task-key">{row.task.key}</span><span class={`priority-pill priority-${row.task.priority}`}>{priorityLabels[row.task.priority]}</span>{#if taskReleaseName(row.task)}<span class="release-chip">{taskReleaseName(row.task)}</span>{/if}</span><strong>{row.task.title}</strong><span class="work-project-name">{row.project?.name || 'Project'} · {row.column?.name || 'In progress'}</span></span><span class="live-work-state"><AgentPulse task={row.task} now={live.pulseClock} actorLabel={agentLabelForTask(row.task)} /></span><span class="row-arrow">→</span></button>{/each}{:else}<p class="live-work-empty">No work is waiting for verification.</p>{/if}</section>
    {/if}
    {#if myWork.myWorkFilter === 'all' || myWork.myWorkFilter === 'working'}
      <section class="live-work-group" aria-labelledby="working-heading"><div class="live-work-group-heading"><div><h3 id="working-heading">Working</h3><p>Agents actively moving tasks forward.</p></div><strong>{myWork.myWorkWorkingRows.length}</strong></div>{#if myWork.myWorkWorkingRows.length}{#each myWork.myWorkWorkingRows as row (row.task.id)}<button class="work-row live-work-row" type="button" on:click={() => openWorkTask(row.task)}><span class="work-project-dot" style={`--project-color: ${row.project?.color || '#6d5efc'}`}></span><span class="work-main"><span class="work-row-top"><span class="task-key">{row.task.key}</span><span class={`priority-pill priority-${row.task.priority}`}>{priorityLabels[row.task.priority]}</span>{#if taskReleaseName(row.task)}<span class="release-chip">{taskReleaseName(row.task)}</span>{/if}</span><strong>{row.task.title}</strong><span class="work-project-name">{row.project?.name || 'Project'} · {row.column?.name || 'In progress'}</span></span><span class="live-work-state"><AgentPulse task={row.task} now={live.pulseClock} actorLabel={agentLabelForTask(row.task)} /></span><span class="row-arrow">→</span></button>{/each}{:else}<p class="live-work-empty">No agents are actively working right now.</p>{/if}</section>
    {/if}
  </section>
{/if}
